// Extraer chat_id, texto del paciente y nombre
const item = $input.first().json;
let chat_id = null;
let text = '';
let user_name = '';

if (item.message) {
  chat_id = String(item.message.chat.id);
  text = item.message.text || '';
  user_name = item.message.from.first_name || 'Paciente';
} else if (item.callback_query) {
  chat_id = String(item.callback_query.message.chat.id);
  text = item.callback_query.data || '';
  user_name = item.callback_query.from.first_name || 'Paciente';
}

return [{
  json: {
    chat_id,
    text,
    user_name,
    sessionId: chat_id
  }
}];

const input = typeof query === 'string' ? JSON.parse(query) : query;
const fecha = input.fecha || '2026-09-15';
const hora = input.hora || null;
const esp = input.especialidad || 'General';

if (hora === '15:00') {
  return JSON.stringify({
    disponible: false,
    mensaje: 'A las 15:00 el gabinete está ocupado por cirugía/desinfección. Horarios contiguos libres: 15:45, 16:30.'
  });
}

if (hora) {
  return JSON.stringify({
    disponible: true,
    fecha: fecha,
    hora: hora,
    especialidad: esp,
    mensaje: 'Horario libre confirmado.'
  });
}

return JSON.stringify({
  disponible: true,
  fecha: fecha,
  especialidad: esp,
  huecos_recomendados: ['10:30', '16:00', '17:30']
});

